"use client";

import { cva, type VariantProps } from "class-variance-authority";
import { forwardRef } from "react";
import { cn } from "@/lib/cn";

/**
 * ボタン。高さは「指かマウスか」で自動（マウス 36px／指 44px）。押すと少し縮む。
 * 1つの画面で primary（塗りつぶし）は1個まで。ほかは secondary か ghost。
 * 使えない状態（disabled）は極力使わず、押されたときに理由を出す。
 */
export const buttonVariants = cva(
  "inline-flex h-hit items-center justify-center gap-1.5 whitespace-nowrap rounded-md px-3.5 text-sm font-medium select-none " +
    "transition-[background-color,border-color,color,scale] duration-[var(--wk-dur-fast)] ease-out active:scale-(--wk-press) active:duration-[var(--wk-dur-press)] " +
    "aria-busy:cursor-progress aria-busy:opacity-85 disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        primary: "bg-accent text-on-accent hover:bg-[color-mix(in_oklab,var(--wk-accent)_88%,var(--wk-fg))]",
        secondary: "border border-line bg-surface text-fg hover:bg-surface-2",
        // 主ボタンは1画面に1つ。同じ画面の2つ目の「進める」操作はこちら（主色の淡い地）
        soft: "bg-accent-soft text-accent-text hover:bg-[color-mix(in_oklab,var(--wk-accent-soft)_85%,var(--wk-accent))]",
        ghost: "text-fg-2 hover:bg-surface-2 hover:text-fg",
        danger: "text-danger hover:bg-danger-soft",
      },
      size: {
        md: "",
        lg: "h-12 px-5 text-base",
        icon: "w-hit px-0",
      },
    },
    defaultVariants: { variant: "secondary", size: "md" },
  },
);

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>;

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { className, variant, size, type = "button", ...props },
  ref,
) {
  return <button ref={ref} type={type} className={cn(buttonVariants({ variant, size }), className)} {...props} />;
});

/**
 * 押してから結果が出るまで時間がかかるボタン。
 * pending の間は「◯◯しています…」に変わり、二度押しを受け付けない（disabled にはしない＝色が薄くならない）。
 */
export function PendingButton({
  pending,
  pendingLabel,
  children,
  onClick,
  ...props
}: ButtonProps & { pending: boolean; pendingLabel: string }) {
  return (
    <Button
      {...props}
      aria-busy={pending || undefined}
      onClick={(e) => {
        if (pending) {
          e.preventDefault();
          return;
        }
        onClick?.(e);
      }}
    >
      {pending ? (
        <>
          <span aria-hidden className="wk-spin size-3.5 rounded-full border-2 border-current border-r-transparent" />
          {pendingLabel}
        </>
      ) : (
        children
      )}
    </Button>
  );
}

"use client";

/**
 * 確認ダイアログ。元に戻せない操作のときだけ使う（取り消せる操作は確認を挟まず、トーストの「取り消す」で戻す）。
 * 押すボタンには何が起きるかを動詞で書く（「OK」にしない）。
 */
import { AlertDialog } from "@base-ui/react/alert-dialog";
import { Button } from "./button";

export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  body,
  confirmLabel,
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  body: string;
  confirmLabel: string;
  onConfirm: () => void;
}) {
  return (
    <AlertDialog.Root open={open} onOpenChange={onOpenChange}>
      <AlertDialog.Portal>
        <AlertDialog.Backdrop className="fixed inset-0 z-50 bg-scrim transition-opacity duration-[var(--wk-dur-base)] ease-out data-[ending-style]:opacity-0 data-[ending-style]:duration-[var(--wk-dur-fast)] data-[starting-style]:opacity-0" />
        <AlertDialog.Popup className="fixed top-1/2 left-1/2 z-50 grid w-[min(400px,calc(100vw-32px))] -translate-x-1/2 -translate-y-1/2 gap-3 rounded-lg bg-surface p-5 shadow-float transition-[opacity,scale] duration-[var(--wk-dur-base)] ease-out data-[ending-style]:scale-(--wk-pop) data-[ending-style]:opacity-0 data-[ending-style]:duration-[var(--wk-dur-exit)] data-[starting-style]:scale-(--wk-pop) data-[starting-style]:opacity-0">
          <AlertDialog.Title className="text-lg font-semibold">{title}</AlertDialog.Title>
          <AlertDialog.Description className="text-sm text-fg-2">{body}</AlertDialog.Description>
          <div className="mt-2 flex justify-end gap-2">
            <AlertDialog.Close render={<Button variant="ghost" />}>やめる</AlertDialog.Close>
            <Button
              className="bg-danger text-on-danger hover:bg-[color-mix(in_oklab,var(--wk-danger)_88%,var(--wk-fg))]"
              onClick={() => {
                onConfirm();
                onOpenChange(false);
              }}
            >
              {confirmLabel}
            </Button>
          </div>
        </AlertDialog.Popup>
      </AlertDialog.Portal>
    </AlertDialog.Root>
  );
}

"use client";

/**
 * 数字が回って止まる表示（数字カード用）。値が変わったときだけ、今の数から 0.24 秒で数え直す（何が増えた・減ったかが分かる）。
 * 画面を開いたときは最初から目標の数を出す（開くたびに 0 から数えると、毎日見る画面ではうるさく、読めるまで待たされる）。
 * 動きを減らす設定では数えずに切り替える。
 */
import { animate, motion, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import { useEffect } from "react";

export function CountUp({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const mv = useMotionValue(value);
  const shown = useTransform(mv, (v) => String(Math.round(v)));

  useEffect(() => {
    if (reduce) {
      mv.set(value);
      return;
    }
    const c = animate(mv, value, { duration: 0.24, ease: [0.23, 1, 0.32, 1] }); // --wk-dur-base・--wk-ease-out
    return () => c.stop();
  }, [value, reduce, mv]);

  return (
    <>
      <motion.span aria-hidden className="num">
        {shown}
      </motion.span>
      {/* 読み上げには最終の数だけを渡す */}
      <span className="sr-only">{value}</span>
    </>
  );
}

/**
 * 表 → カードの一覧。768px 以上は普通の表、それより狭いと1行を1枚のカードにして縦に並べる（横にずらさなくても全部読める）。
 * 既存のツールの <table> を置き換えるときに使う。列の定義を1回書けば、表とカードの両方がそこから作られる。
 *
 *   <DataList
 *     label="お客さま"
 *     rows={customers}
 *     rowKey={(c) => c.id}
 *     onOpen={(c) => router.push(`/customers/${c.id}`)}
 *     columns={[
 *       { key: "name", label: "名前", cell: (c) => c.name, role: "title" },
 *       { key: "status", label: "状態", cell: (c) => <Badge>{c.status}</Badge>, role: "badge" },
 *       { key: "tel", label: "電話", cell: (c) => c.tel },
 *       { key: "amount", label: "金額", cell: (c) => yen(c.amount), align: "end" },
 *     ]}
 *   />
 *
 * role … カードでの置き場所。title＝1行目の題名（1つだけ）／badge＝題名の横の印／無し＝「名前：値」の行／hidden＝カードでは出さない
 * 表では題名以外の列は折り返さない（電話番号・金額・日付が途中で切れないように）。長い文章の列は wrap: true にする
 */
import { ChevronRight } from "lucide-react";
import { cn } from "@/lib/cn";

export type DataColumn<T> = {
  key: string;
  label: string;
  cell: (row: T) => React.ReactNode;
  role?: "title" | "badge" | "hidden";
  align?: "start" | "end";
  /** 表での列の幅（例："120px"・"20%"）。無ければ中身に合わせる */
  width?: string;
  /** 表でこの列の折り返しを許す（題名の列は常に折り返す） */
  wrap?: boolean;
};

export function DataList<T>({
  label,
  rows,
  columns,
  rowKey,
  onOpen,
  empty,
}: {
  /** 一覧の名前（読み上げ用。例：「お客さま」） */
  label: string;
  rows: T[];
  columns: DataColumn<T>[];
  rowKey: (row: T) => string | number;
  /** 行を押したとき（詳細へ移る・シートを開く）。無ければ押せない一覧になる */
  onOpen?: (row: T) => void;
  /** 0件のときに出す物（components/kit/feedback.tsx の EmptyState など） */
  empty?: React.ReactNode;
}) {
  if (rows.length === 0) return <>{empty}</>;
  const title = columns.find((c) => c.role === "title") ?? columns[0];
  const badges = columns.filter((c) => c.role === "badge");
  const fields = columns.filter((c) => c !== title && !c.role);

  return (
    <div className="overflow-hidden rounded-md border border-line bg-surface">
      {/* 768px 以上：表 */}
      {/* 列が多くて収まらないときは、表の中だけ横にずらせる（画面全体は横にずれない） */}
      <div className="hidden overflow-x-auto rail:block">
        <table aria-label={label} className="w-full border-collapse text-sm">
          <thead>
            <tr className="border-b border-line text-left text-xs text-fg-3">
              {columns.map((c) => (
                <th key={c.key} scope="col" style={c.width ? { width: c.width } : undefined} className={cn("h-9 px-3 font-normal whitespace-nowrap", c.align === "end" && "text-right")}>
                  {c.label}
                </th>
              ))}
              {onOpen && <th aria-hidden className="w-hit" />}
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr
                key={rowKey(r)}
                className={cn("border-b border-line last:border-b-0", onOpen && "transition-colors duration-[var(--wk-dur-fast)] hover:bg-surface-2")}
              >
                {columns.map((c) => (
                  <td key={c.key} className={cn("h-row px-3 py-2 align-middle", c.align === "end" && "num text-right", c === title ? "min-w-48 font-medium" : !c.wrap && "whitespace-nowrap")}>
                    {c === title && onOpen ? <OpenButton onClick={() => onOpen(r)}>{c.cell(r)}</OpenButton> : c.cell(r)}
                  </td>
                ))}
                {onOpen && (
                  <td aria-hidden className="pr-2 text-fg-3">
                    <ChevronRight size={16} />
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 767px 以下：1行＝1枚のカード */}
      <ul aria-label={label} className="rail:hidden">
        {rows.map((r) => (
          <li
            key={rowKey(r)}
            className={cn("relative grid gap-1.5 border-b border-line px-4 py-3 last:border-b-0", onOpen && "active:bg-surface-2")}
          >
            <div className="flex min-w-0 items-start gap-2">
              <div className="min-w-0 flex-1 font-medium">{onOpen ? <OpenButton stretch onClick={() => onOpen(r)}>{title.cell(r)}</OpenButton> : title.cell(r)}</div>
              {badges.length > 0 && <div className="flex flex-none flex-wrap items-center justify-end gap-1">{badges.map((c) => <span key={c.key}>{c.cell(r)}</span>)}</div>}
              {onOpen && <ChevronRight aria-hidden size={18} className="mt-0.5 flex-none text-fg-3" />}
            </div>
            {fields.length > 0 && (
              <dl className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-0.5 text-sm">
                {fields.map((c) => (
                  <div key={c.key} className="contents">
                    <dt className="text-fg-3">{c.label}</dt>
                    <dd className={cn("min-w-0 break-words text-fg-2", c.align === "end" && "num")}>{c.cell(r)}</dd>
                  </div>
                ))}
              </dl>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

/** 題名を押せるボタンにする。stretch はカード全体に押せる範囲を広げる（表の行は Safari が position を効かせないので広げない） */
function OpenButton({ onClick, stretch, children }: { onClick: () => void; stretch?: boolean; children: React.ReactNode }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "min-h-hit min-w-0 text-left underline-offset-4 hover:underline",
        stretch && "min-h-0 hover:no-underline after:absolute after:inset-0 focus-visible:outline-none focus-visible:after:outline-2 focus-visible:after:-outline-offset-2 focus-visible:after:outline-accent",
      )}
    >
      {children}
    </button>
  );
}

"use client";

/**
 * 右下の丸い主ボタン（スマホだけ）。親指が届く位置に、その画面でいちばん多い操作を1つだけ置く。
 * 下タブのすぐ上に浮かせる。768px 以上では出さない（見出しの右のボタンを使う）。
 */
import { cn } from "@/lib/cn";

export function Fab({ label, onClick, children, className }: { label: string; onClick: () => void; children: React.ReactNode; className?: string }) {
  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      onClick={onClick}
      className={cn(
        "wk-fab fixed right-4 z-30 grid size-14 place-items-center rounded-full bg-accent text-on-accent shadow-float transition-[scale] duration-[var(--wk-dur-fast)] ease-out active:scale-(--wk-press-round) active:duration-[var(--wk-dur-press)] rail:hidden",
        className,
      )}
      style={{ bottom: "calc(var(--wk-tabbar-h) + var(--wk-tabbar-gap) + var(--wk-safe-b) + 14px)", right: "max(16px, env(safe-area-inset-right, 0px))" }}
    >
      {children}
    </button>
  );
}

import { CircleAlert, type LucideIcon } from "lucide-react";
import { cn } from "@/lib/cn";

/** 空の状態。「何もありません」で終わらせず、次にできることを1つ出す */
export function EmptyState({
  icon: Icon,
  title,
  body,
  action,
  className,
}: {
  icon?: LucideIcon;
  title: string;
  body?: string;
  action?: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("grid justify-items-center gap-2 px-5 py-10 text-center", className)}>
      {Icon && <Icon aria-hidden size={28} className="mb-1 text-fg-3" />}
      <h3 className="text-base font-semibold">{title}</h3>
      {body && <p className="max-w-[36ch] text-sm text-fg-3">{body}</p>}
      {action && <div className="mt-2">{action}</div>}
    </div>
  );
}

/** 読み込みの骨。150ms 待ってから出るので、速く読み込めたときはチラつかない */
export function Skeleton({ className }: { className?: string }) {
  return <div aria-hidden className={cn("wk-skeleton h-4", className)} />;
}

/** その場に出すエラー。何が起きたか＋どうすればいいかを1文で */
export function InlineError({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <p
      role="alert"
      // 出た瞬間に目が向くよう、少し上からふわっと出す（揺らしはしない）
      className={cn(
        "flex items-start gap-1.5 text-sm text-danger transition-[opacity,translate] duration-[var(--wk-dur-fast)] ease-out starting:opacity-0 motion-safe:starting:-translate-y-1",
        className,
      )}
    >
      <CircleAlert aria-hidden size={16} className="mt-0.5 flex-none" />
      <span>{children}</span>
    </p>
  );
}

/** 数字のカード。注意が要るとき（tone="alert"）は面ごと赤みにして一目で分かるようにする */
export function StatCard({
  label,
  value,
  unit,
  tone = "plain",
}: {
  label: string;
  value: React.ReactNode;
  unit?: string;
  tone?: "plain" | "alert";
}) {
  return (
    <div className={cn("rounded-md border px-4 py-3.5", tone === "alert" ? "border-transparent bg-danger-soft text-danger" : "border-line bg-surface")}>
      <div className={cn("text-xs tracking-wide", tone === "alert" ? "text-danger" : "text-fg-3")}>{label}</div>
      <div className="num mt-0.5 text-[30px] leading-tight font-semibold">
        {value}
        {unit && <small className={cn("ml-0.5 text-sm font-normal", tone === "alert" ? "text-danger" : "text-fg-3")}>{unit}</small>}
      </div>
    </div>
  );
}

/** 画面の見出し。上に貼り付き、下の内容がすりガラス越しに透ける */
export function PageHeader({ title, sub, actions }: { title: string; sub?: React.ReactNode; actions?: React.ReactNode }) {
  return (
    <header className="wk-glass-top sticky top-0 z-20 -mx-4 mb-2 flex items-end justify-between gap-3 px-4 pt-[calc(18px+env(safe-area-inset-top,0px))] pb-3 rail:-mx-7 rail:px-7 rail:pt-6">
      <div className="min-w-0">
        <h1 className="text-xl leading-tight font-semibold">{title}</h1>
        {sub && <p className="mt-0.5 text-sm text-fg-3">{sub}</p>}
      </div>
      {actions && <div className="flex flex-none gap-2">{actions}</div>}
    </header>
  );
}

/** 本文の箱。幅を読みやすい範囲に抑え、左右の余白をそろえる */
export function Page({ children, className }: { children: React.ReactNode; className?: string }) {
  return <div className={cn("mx-auto w-full max-w-[920px] px-4 pb-12 rail:px-7", className)}>{children}</div>;
}

"use client";

import { cn } from "@/lib/cn";

/** 2〜4個から1つ選ぶ切り替え。選んだものだけ白い下地が付く */
export function Segmented<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { value: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div role="group" aria-label={label} className="inline-flex gap-0.5 rounded-full border border-line bg-surface-2 p-[3px]">
      {options.map((o) => (
        <button
          key={o.value}
          type="button"
          aria-pressed={value === o.value}
          onClick={() => onChange(o.value)}
          className={cn(
            "min-h-[30px] rounded-full px-3 text-sm text-fg-2 transition-[color,background-color,box-shadow,scale] duration-[var(--wk-dur-fast)] ease-out active:scale-(--wk-press) active:duration-[var(--wk-dur-press)] pointer-coarse:min-h-hit",
            value === o.value && "bg-surface text-fg shadow-sm",
          )}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

/** 絞り込みなどのチップ（複数並べて1つ選ぶ） */
export function Chip({ pressed, onClick, children }: { pressed: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      aria-pressed={pressed}
      onClick={onClick}
      className={cn(
        "inline-flex h-hit items-center gap-1.5 rounded-full border px-3 text-sm transition-[color,background-color,border-color,scale] duration-[var(--wk-dur-fast)] ease-out active:scale-(--wk-press) active:duration-[var(--wk-dur-press)]",
        pressed ? "border-fg bg-fg text-canvas" : "border-line bg-surface text-fg-2 hover:text-fg",
      )}
    >
      {children}
    </button>
  );
}

"use client";

/**
 * シート。スマホ（767px 以下）は下から出て、つまみを下に引くと閉じる。PC・タブレットは右から浮いた引き出しで出る。
 * 作業を止めるもの（追加・編集）は背景を暗くする。閉じたら、開く前に触っていた場所へ戻る。
 * 開いたら中の最初の入力欄（無ければ最初のボタン）へフォーカスを移す。出ていたお知らせは消す（シートの入力欄に重なるため）。
 */
import { Drawer } from "vaul";
import { X } from "lucide-react";
import { toast } from "sonner";
import { useEffect, useSyncExternalStore } from "react";
import { cn } from "@/lib/cn";

const query = "(max-width: 47.99rem)";
function subscribe(cb: () => void) {
  const m = window.matchMedia(query);
  m.addEventListener("change", cb);
  return () => m.removeEventListener("change", cb);
}
export function useIsPhone() {
  return useSyncExternalStore(subscribe, () => window.matchMedia(query).matches, () => false);
}

export function Sheet({
  open,
  onOpenChange,
  title,
  description,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
  children: React.ReactNode;
}) {
  const phone = useIsPhone();
  useEffect(() => {
    if (open) toast.dismiss();
  }, [open]);
  return (
    <Drawer.Root open={open} onOpenChange={onOpenChange} direction={phone ? "bottom" : "right"} repositionInputs={false} autoFocus>
      <Drawer.Portal>
        <Drawer.Overlay className="fixed inset-0 z-50 bg-scrim" />
        <Drawer.Content
          onOpenAutoFocus={(e) => {
            // 既定は最初に押せる物（PC では右上の ×）。入力欄があればそこへ移す（開いてすぐ書ける）
            const field = (e.currentTarget as HTMLElement | null)?.querySelector<HTMLElement>(
              "input:not([type=hidden]):not(:disabled), textarea:not(:disabled), select:not(:disabled)",
            );
            if (field) {
              e.preventDefault();
              field.focus({ preventScroll: true });
            }
          }}
          className={cn(
            "fixed z-50 flex flex-col bg-surface shadow-float outline-none",
            phone
              ? "inset-x-0 bottom-0 max-h-[88dvh] rounded-t-[22px] pb-[env(safe-area-inset-bottom,0px)]"
              : "top-3 right-3 bottom-3 w-[min(420px,calc(100vw-24px))] rounded-lg",
          )}
        >
          {phone && <div aria-hidden className="mx-auto mt-2.5 mb-1 h-[5px] w-10 flex-none rounded-full bg-line" />}
          <div className="flex items-start justify-between gap-3 px-5 pt-4 pb-2 rail:px-6 rail:pt-5">
            <div className="min-w-0">
              <Drawer.Title className="text-lg font-semibold">{title}</Drawer.Title>
              {description ? (
                <Drawer.Description className="mt-0.5 text-sm text-fg-3">{description}</Drawer.Description>
              ) : (
                <Drawer.Description className="sr-only">{title}</Drawer.Description>
              )}
            </div>
            {!phone && (
              <Drawer.Close className="-mt-1 -mr-2 grid size-hit place-items-center rounded-md text-fg-3 transition-colors hover:bg-surface-2 hover:text-fg active:bg-surface-2" aria-label="閉じる">
                <X aria-hidden size={18} />
              </Drawer.Close>
            )}
          </div>
          <div className="overflow-y-auto overscroll-contain px-5 pb-6 rail:px-6">{children}</div>
        </Drawer.Content>
      </Drawer.Portal>
    </Drawer.Root>
  );
}

"use client";

/**
 * 手順の表示（1 / 3 のような進み具合）。手順フォームの上に置く。
 * 終わった手順は ✓、今の手順は塗りつぶし、先の手順は線だけ。押して前の手順に戻れる。
 */
import { Check } from "lucide-react";
import { cn } from "@/lib/cn";

export function Steps({ steps, current, onJump }: { steps: string[]; current: number; onJump?: (i: number) => void }) {
  return (
    <ol aria-label="手順" className="flex items-center gap-1.5">
      {steps.map((label, i) => {
        const done = i < current;
        const now = i === current;
        return (
          <li key={label} className="flex min-w-0 flex-1 items-center gap-1.5 last:flex-none">
            <button
              type="button"
              disabled={!done || !onJump}
              onClick={() => onJump?.(i)}
              aria-current={now ? "step" : undefined}
              aria-label={`${i + 1}. ${label}${done ? "（済み・押すと戻る）" : now ? "（いまの手順）" : ""}`}
              className="flex min-h-hit min-w-hit flex-none items-center justify-center gap-1.5 disabled:cursor-default"
            >
              <span
                className={cn(
                  "num grid size-6 flex-none place-items-center rounded-full text-xs font-semibold transition-colors",
                  done ? "bg-accent text-on-accent" : now ? "bg-fg text-canvas" : "border border-line text-fg-3",
                )}
              >
                {done ? <Check aria-hidden size={14} strokeWidth={3} /> : i + 1}
              </span>
              <span className={cn("text-xs whitespace-nowrap", now ? "font-medium text-fg" : "text-fg-3", !now && "max-rail:sr-only")}>{label}</span>
            </button>
            {i < steps.length - 1 && <span aria-hidden className={cn("h-px min-w-3 flex-1 transition-colors", done ? "bg-accent" : "bg-line")} />}
          </li>
        );
      })}
    </ol>
  );
}

