/** 結果のお知らせ。undo を渡すと「取り消す」ボタンが付く */
export function notify(message: string, undo?: () => void) {
  toast(message, undo ? { action: { label: "取り消す", onClick: undo } } : undefined);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** クラス名を条件付きで足し、Tailwind の同じ種類の指定は後ろを優先する */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

/**
 * 見た目の設定（明るさ・行の高さ）。<html> の data 属性に書き、このブラウザに覚えさせる。
 * 設定画面と ⌘K パレットの両方から変えるので、ここに1つだけ置く。
 */
import { useSyncExternalStore } from "react";

export type Theme = "system" | "light" | "dark";
export type Density = "comfy" | "compact";

const listeners = new Set<() => void>();
const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};

function write(name: "theme" | "density" | "palette", value: string, key: string) {
  const d = document.documentElement;
  if (value) d.dataset[name] = value;
  else delete d.dataset[name];
  try {
    if (value) localStorage.setItem(key, value);
    else localStorage.removeItem(key);
  } catch {}
  listeners.forEach((l) => l());
}

/** 明るさを固定しているアプリ（<WorkspaceBoot forceTheme="…">）か */
export const themeLocked = () => typeof document !== "undefined" && !!document.documentElement.dataset.themeLocked;

export const setTheme = (t: Theme) => {
  if (themeLocked()) return;
  write("theme", t === "system" ? "" : t, "wk.theme");
};
export const setDensity = (d: Density) => write("density", d === "comfy" ? "" : d, "wk.density");

export function useTheme(): Theme {
  return (useSyncExternalStore(subscribe, () => document.documentElement.dataset.theme ?? "", () => "") || "system") as Theme;
}
export function useDensity(): Density {
  return (useSyncExternalStore(subscribe, () => document.documentElement.dataset.density ?? "", () => "") || "comfy") as Density;
}

/** 指で触る端末か（ボタンの大きさや、長押し・… ボタンの出し分けに使う） */
const coarseQuery = "(pointer: coarse)";
function subscribeCoarse(cb: () => void) {
  const m = window.matchMedia(coarseQuery);
  m.addEventListener("change", cb);
  return () => m.removeEventListener("change", cb);
}
export function useCoarsePointer() {
  return useSyncExternalStore(subscribeCoarse, () => window.matchMedia(coarseQuery).matches, () => false);
}

/** 1280px 以上（サイドバーと右の詳細パネルを並べられる幅）か */
const wideQuery = "(min-width: 80rem)";
function subscribeWide(cb: () => void) {
  const m = window.matchMedia(wideQuery);
  m.addEventListener("change", cb);
  return () => m.removeEventListener("change", cb);
}
export function useWide() {
  return useSyncExternalStore(subscribeWide, () => window.matchMedia(wideQuery).matches, () => false);
}

/**
 * テーマ（色・文字・角丸のひとそろい）。<html data-palette="…">。グラファイトは指定なし（基準のトークンそのもの）。
 * 一覧は packages/themes が生成する（仕上げた12種）。
 */
export function setPalette(id: string) {
  write("palette", id === "graphite" ? "" : id, "wk.palette");
  // グラファイトも名前で覚える（アプリの既定テーマが別のときに、グラファイトを選んだことを残すため）
  try {
    localStorage.setItem("wk.palette", id);
  } catch {}
}
export function usePalette(): string {
  return useSyncExternalStore(subscribe, () => document.documentElement.dataset.palette ?? "", () => "") || "graphite";
}

"use client";

/**
 * 長押し（指で触る端末だけ）。0.45 秒押し続けると、押している物が少し沈み（data-held）、軽く震える。
 * シートは「指を離したとき」に開く（押したまま開くと、指を離した瞬間にシートが閉じてしまうため）。
 * 8px 以上動いたらスクロールとみなして取り消す。長押しのあとに来る「タップ」は捨てる。
 * マウスでは何もしない（マウスは … ボタンで操作する）。
 */
import { useRef } from "react";

const DELAY = 450;
const SLOP = 8;

export function useLongPress<T>(onLongPress: (item: T) => void) {
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const start = useRef<[number, number] | null>(null);
  const fired = useRef(false);
  const held = useRef<HTMLElement | null>(null);

  const cancel = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
    start.current = null;
    if (held.current) delete held.current.dataset.held;
    held.current = null;
  };

  return {
    /** 行やカードに付ける */
    bind: (item: T) => ({
      onPointerDown: (e: React.PointerEvent) => {
        if (e.pointerType === "mouse" || (e.target as HTMLElement).closest("[data-no-longpress]")) return;
        fired.current = false;
        start.current = [e.clientX, e.clientY];
        const el = e.currentTarget as HTMLElement;
        timer.current = setTimeout(() => {
          fired.current = true;
          timer.current = null;
          held.current = el;
          el.dataset.held = "";
          try {
            navigator.vibrate?.(8);
          } catch {}
        }, DELAY);
      },
      onPointerMove: (e: React.PointerEvent) => {
        if (start.current && Math.hypot(e.clientX - start.current[0], e.clientY - start.current[1]) > SLOP) cancel();
      },
      onPointerUp: () => {
        const open = fired.current;
        cancel();
        // 指を離した直後の「タップ」が済んでから開く
        if (open) setTimeout(() => onLongPress(item), 0);
      },
      onPointerCancel: () => {
        cancel();
        fired.current = false;
      },
      // 長押し中に OS のメニュー（コピーなど）を出さない
      onContextMenu: (e: React.MouseEvent) => {
        if (fired.current || timer.current) e.preventDefault();
      },
    }),
    /** タップの処理の先頭で呼ぶ。長押しの直後なら true（＝そのタップは無視する） */
    consumed: () => {
      const f = fired.current;
      fired.current = false;
      return f;
    },
  };
}
